		[Test]
		public void TestGetLatestTariffDate()
		{
			Assert.Multiple(() =>
			{
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream("Invalid"));
				Assert.Throws<UnhandledApplicationException>(() => Downloader.GetLatestTariffDate(null), "Invalid Response Received");
				LoggerMock.Verify(l => l.Log(LogType.ReviewRequired, "Failed to get latest Tariff date from the source after 3 retries", It.IsAny<object>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				Assert.AreEqual(new DateTime(2024, 6, 30), Downloader.GetLatestTariffDate(null), "No last processed date");
				LoggerMock.Verify(l => l.Log(LogType.Info, "Requesting data from", It.IsAny<object>()), Times.AtLeastOnce);
				LoggerMock.Verify(l => l.Log(LogType.Info, "Data received from", It.IsAny<object>()), Times.AtLeastOnce);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				Assert.AreEqual(new DateTime(2024, 6, 30), Downloader.GetLatestTariffDate(new DateTime(2024, 4, 10)), "Past Last processed date");

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				Assert.IsNull(Downloader.GetLatestTariffDate(new DateTime(2025, 4, 10)), "Future Last processed date");
			});
		}

		[Test]
		public void TestDownloadPdfFiles()
		{
			Assert.Multiple(() =>
			{
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				Assert.IsNull(Downloader.DownloadPdfFiles(new DateTime(2024, 5, 22)), "Unlisted date");
				LoggerMock.Verify(l => l.Log(LogType.Warning, "No tariffId found for the date", It.IsAny<DateTime>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				Assert.IsNull(Downloader.DownloadPdfFiles(new DateTime(2024, 6, 30)), "Valid date, Part Id missing");
				LoggerMock.Verify(l => l.Log(LogType.Warning, "No partId found for the tariffId", It.IsAny<string>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU1")).Returns(GetStream(ValidTariffFor30June2024Response));
				var tempFolder = TestHelper.CreateTempFolder();
				MockLocationProvider.Setup(x => x.GetPdfDownloadFolder(It.IsAny<DateTime>())).Returns(tempFolder);
				Assert.AreEqual(tempFolder, Downloader.DownloadPdfFiles(new DateTime(2024, 6, 30)), "Valid date, section missing");
				LoggerMock.Verify(l => l.Log(LogType.Warning, "No sections found for the partId", It.IsAny<string>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU1")).Returns(GetStream(ValidTariffFor30June2024Response));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU3")).Returns(GetStream(ValidTariffFor30June2024PartIIResponse));

				Assert.AreEqual(tempFolder, Downloader.DownloadPdfFiles(new DateTime(2024, 6, 30)), "Valid date, files missing");
				LoggerMock.Verify(l => l.Log(LogType.Warning, "No files found for the sectionId", It.IsAny<string>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU1")).Returns(GetStream(ValidTariffFor30June2024Response));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU3")).Returns(GetStream(ValidTariffFor30June2024PartIIResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTYx")).Returns(GetStream(ValidTariffFor30June2024PartIISectionIResponse));

				Assert.AreEqual(tempFolder, Downloader.DownloadPdfFiles(new DateTime(2024, 6, 30)), "Valid date, files missing");
				LoggerMock.Verify(l => l.Log(LogType.Warning, "No files found for the fileId", It.IsAny<string>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU1")).Returns(GetStream(ValidTariffFor30June2024Response));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU3")).Returns(GetStream(ValidTariffFor30June2024PartIIResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTYx")).Returns(GetStream(ValidTariffFor30June2024PartIISectionIResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY2MDkw")).Returns(GetStream(ValidTariffFor30June2024PartIIFile1Response));

				Assert.AreEqual(tempFolder, Downloader.DownloadPdfFiles(new DateTime(2024, 6, 30)), "Valid date, content missing for file path");
				LoggerMock.Verify(l => l.Log(LogType.Warning, "No response received for the file path", It.IsAny<string>()), Times.Once);

				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + AppConfig.Tariff.TariffSubUrl)).Returns(GetStream(ValidTariffMainPageResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU1")).Returns(GetStream(ValidTariffFor30June2024Response));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTU3")).Returns(GetStream(ValidTariffFor30June2024PartIIResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY1OTYx")).Returns(GetStream(ValidTariffFor30June2024PartIISectionIResponse));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.BaseUrl + "MTY2MDkw")).Returns(GetStream(ValidTariffFor30June2024PartIIFile1Response));
				MockHttpClient.Setup(x => x.GetAsync(AppConfig.Tariff.ContentBaseUrl + "CONTENTREPO/Customs/Tariff/Tariff(ason30.06.2024)/CUSTOMS_TARIFF_VOL-I/chap-1.pdf")).Returns(GetStream(ValidTariffFor30June2024PartIIChap1Response));

				Assert.AreEqual(tempFolder, Downloader.DownloadPdfFiles(new DateTime(2024, 6, 30)), "Valid date, file downloaded");
				Assert.AreEqual(1, Directory.GetFiles(tempFolder).Length, "Created files count");

				Directory.Delete(tempFolder, true);
			});
		}

		Task<Stream> GetStream(string content)
		{
			var memoryStream = new MemoryStream();
			using (var writer = new StreamWriter(memoryStream, Encoding.UTF8, leaveOpen: true))
			{
				writer.Write(content);
				writer.Flush();
			}
			memoryStream.Position = 0;
			return Task.FromResult<Stream>(memoryStream);
		}

